def compute(vars):
    capital_lease_obligations = vars["v1"]
    total_contractual_obligations = vars["v2"]

    if total_contractual_obligations == 0:
        return None

    percentage = (
        capital_lease_obligations / total_contractual_obligations
    ) * 100

    return {
        "value": percentage,
        "trace": {
            "capital_lease_obligations": capital_lease_obligations,
            "total_contractual_obligations": total_contractual_obligations,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage",
            },
        },
    }
